}
.life-pro-active:after{
  content:"";
  position:fixed;
  inset:0;
  z-index:0;
  pointer-events:none;
  opacity:.34;
  background:
    linear-gradient(112deg,transparent 0 18%,rgba(255,255,255,.035) 21%,transparent 24% 58%,rgba(255,148,54,.025) 62%,transparent 66%),
