.life-page-transition{
  pointer-events:none!important;
  display:block!important;
  background:transparent!important;
  backdrop-filter:none!important;
}
.life-page-transition-inner{
  position:fixed!important;
  top:78px!important;
  right:max(18px,calc((100vw - 1180px)/2))!important;
  width:auto!important;
  min-width:210px!important;
  max-width:min(360px,calc(100vw - 36px))!important;
  height:auto!important;
  margin:0!important;
  padding:12px 14px!important;
  border:1px solid rgba(255,255,255,.09)!important;
  border-radius:14px!important;
  background:rgba(13,16,20,.94)!important;
  box-shadow:0 18px 52px rgba(0,0,0,.28)!important;
  display:grid!important;
  grid-template-columns:8px minmax(0,1fr)!important;
  column-gap:10px!important;
  align-items:center!important;
  animation:lifeFinalNavIn .22s cubic-bezier(.2,.8,.2,1) both!important;
}
.life-page-transition.out .life-page-transition-inner{animation:lifeFinalNavOut .18s ease forwards!important}
.life-page-transition-mark{grid-row:1/4!important;width:7px!important;height:7px!important;margin:0!important;align-self:start!important;margin-top:4px!important}
.life-page-transition small{font-size:7px!important;letter-spacing:.15em!important;text-align:left!important;color:#737d87!important}
.life-page-transition b{font-size:13px!important;letter-spacing:-.02em!important;margin:2px 0 0!important;text-align:left!important;color:#eef1f4!important}
.life-page-transition i{grid-column:2!important;width:100%!important;height:2px!important;margin:6px 0 0!important;background:linear-gradient(90deg,#f97316,transparent)!important;transform-origin:left!important}
@keyframes lifeFinalNavIn{from{transform:translateY(-8px);opacity:0}to{transform:none;opacity:1}}
@keyframes lifeFinalNavOut{to{transform:translateY(-5px);opacity:0}}


