:root{
  --life-bg:#07090c;
  --life-bg-2:#0a0d11;
  --life-surface:#0d1116;
  --life-surface-2:#11161c;
  --life-surface-3:#151b22;
  --life-border:rgba(255,255,255,.075);
  --life-border-strong:rgba(255,255,255,.12);
  --life-text:#f5f7f9;
  --life-muted:#8b96a2;
  --life-muted-2:#626e7a;
  --life-orange:#ff7a1a;
  --life-shadow:0 22px 70px rgba(0,0,0,.24);
  --life-shadow-soft:0 12px 36px rgba(0,0,0,.16);
  --life-radius-xl:28px;
  --life-radius-lg:22px;
  --life-radius-md:16px;
  --life-radius-sm:12px;
  --life-ease:cubic-bezier(.2,.75,.25,1);
}
*{box-sizing:border-box}
html{background:var(--life-bg);scroll-behavior:smooth}
