.v18-tabs button:hover{background:rgba(255,255,255,.035)!important;color:#dfe4e9!important}
.v18-tabs button.on{background:rgba(var(--area-rgb,249,115,22),.09)!important;color:#fff!important;box-shadow:inset 0 0 0 1px rgba(var(--area-rgb,249,115,22),.18)!important}


