.life13-extras summary::-webkit-details-marker{display:none}.life13-extras summary>span:first-child{display:flex;flex-direction:column;gap:5px;min-width:0}
.life13-extras summary small{font:750 10px 'JetBrains Mono',monospace;letter-spacing:.1em;color:#dba980}
