.life13-body button,.life13-extras>details>div>button{background:#27303d;color:#fff;border:1px solid rgba(255,255,255,.1);padding:10px 14px;border-radius:12px;margin:6px 7px 0 0;min-height:42px;cursor:pointer;text-align:left;font-size:12px;font-weight:700}
.life13-body button:hover{border-color:#e6ad82;color:#f5c7a5}.life13-body button:disabled{opacity:.4;cursor:not-allowed}
.life13-body .life13-check{display:flex;flex-direction:row;gap:12px;align-items:center;cursor:pointer}.life13-body input[type="checkbox"]{accent-color:#ebb37f;width:18px;height:18px}
