.life13-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;padding:15px 22px}.life13-summary>div{background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.065);padding:12px;border-radius:12px;display:flex;flex-direction:column;gap:6px}.life13-summary small{font-size:10px;color:#a8b4c2}.life13-summary strong{font-size:21px;color:#f5d5b9}
